                    customer_ids.append(i)
        else:
            cl = as_list(coords)
            if cl is not None:
                for i in range(len(cl)):
                    if i != depot_id:
                        customer_ids.append(i)
            else:
                if type(n) is int and n > 0:
                    for i in range(n):
                        if i != depot_id:
                            customer_ids.append(i)

    customer_ids.sort()

    def demand_of(i):
        if is_dict(demands):
            v = demands.get(i, 0)
            return 0 if v is None else v
        dl = as_list(demands)
        if dl is not None and 0 <= i < len(dl):
            v = dl[i]
            return 0 if v is None else v
        return 0

    def coord_of(i):
        if is_dict(coords):
            p = coords.get(i, None)
            if type(p) in (list, tuple) and len(p) >= 2:
                return p[0], p[1]
        cl = as_list(coords)
        if cl is not None and 0 <= i < len(cl):
            p = cl[i]
            if type(p) in (list, tuple) and len(p) >= 2:
                return p[0], p[1]
        return None

    def d(i, j):
        if dist is not None:
            if is_dict(dist):
                row = dist.get(i, None)
                if is_dict(row):
                    v = row.get(j, None)
                    if v is not None:
                        return v
                if type(row) in (list, tuple) and 0 <= j < len(row):
                    v = row[j]
                    if v is not None:
                        return v
            else:
                if type(dist) in (list, tuple) and 0 <= i < len(dist):
                    row = dist[i]
                    if type(row) in (list, tuple) and 0 <= j < len(row):
                        v = row[j]
                        if v is not None:
                            return v
        ci = coord_of(i)
        cj = coord_of(j)
        if ci is not None and cj is not None:
            dx = ci[0] - cj[0]
            dy = ci[1] - cj[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    if capacity is None:
        total_demand = 0
        for c in customer_ids:
            total_demand += demand_of(c)
        capacity = total_demand if total_demand > 0 else 1

    customer_set = {}
    for c in customer_ids:
        customer_set[c] = True

    # Initial singleton routes
    routes = []
    route_of = {}
    for c in customer_ids:
        routes.append([c])
        route_of[c] = len(routes) - 1

    # Clarke-Wright savings
    savings = []
    dep_to = {}
    for c in customer_ids:
        dep_to[c] = d(depot_id, c)

    for a in range(len(customer_ids)):
        i = customer_ids[a]
        di0 = dep_to[i]
        for b in range(a + 1, len(customer_ids)):
            j = customer_ids[b]
            s = di0 + dep_to[j] - d(i, j)
            savings.append((s, i, j))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    def reverse_if_needed(seq, node, at_end):
        if at_end == "tail":
            if seq and seq[-1] == node:
                return seq
            if seq and seq[0] == node:
                return seq[::-1]
        else:
            if seq and seq[0] == node:
                return seq
            if seq and seq[-1] == node:
                return seq[::-1]
        return None

    loads = []
    for c in customer_ids:
        loads.append(demand_of(c))

    active = [True] * len(routes)

    for _, i, j in savings:
        ri = route_of.get(i, None)
        rj = route_of.get(j, None)
        if ri is None or rj is None or ri == rj:
            continue
        if not active[ri] or not active[rj]:
            continue
        if loads[ri] + loads[rj] > capacity:
            continue

        si = routes[ri]
        sj = routes[rj]
        left = reverse_if_needed(si, i, "tail")
        right = reverse_if_needed(sj, j, "head")
        if left is None or right is None:
            continue

        merged = left + right
        routes.append(merged)
        loads.append(loads[ri] + loads[rj])
        active.append(True)
        new_idx = len(routes) - 1

        active[ri] = False
        active[rj] = False
        routes[ri] = []
        routes[rj] = []
        loads[ri] = 0
        loads[rj] = 0
        for c in merged:
            route_of[c] = new_idx

    final_routes = []
    for idx in range(len(routes)):
        if idx < len(active) and active[idx] and routes[idx]:
            final_routes.append(routes[idx])

    def route_cost(seq):
        if not seq:
            return 0
        cost = d(depot_id, seq[0])
        for k in range(len(seq) - 1):
            cost += d(seq[k], seq[k + 1])
        cost += d(seq[-1], depot_id)
        return cost

    def route_load(seq):
        s = 0
        for c in seq:
            s += demand_of(c)
        return s

    # Intra-route 2-opt
    for ridx in range(len(final_routes)):
        seq = final_routes[ridx]
        improved = True
        while improved and len(seq) >= 4:
            improved = False
            best = seq
            best_cost = route_cost(seq)
            nseq = len(seq)
            for a in range(nseq - 1):
                for b in range(a + 1, nseq):
                    cand = seq[:a] + seq[a:b + 1][::-1] + seq[b + 1:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_cost:
                        best = cand
                        best_cost = cc
                        improved = True
            seq = best
        final_routes[ridx] = seq

    # Ensure all customers appear exactly once
    seen = {}
    for r in final_routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customer_ids:
        if c not in seen:
            missing.append(c)

    if missing:
        for c in missing:
            final_routes.append([c])

    # Remove duplicates by first occurrence, preserving feasibility
    assigned = {}
    repaired = []
    for r in final_routes:
        new_r = []
        load = 0
        for c in r:
            if c in customer_set and c not in assigned:
                assigned[c] = True
                new_r.append(c)
                load += demand_of(c)
        if new_r:
            if load <= capacity:
                repaired.append(new_r)
            else:
                current = []
                current_load = 0
                for c in new_r:
                    dc = demand_of(c)
                    if current and current_load + dc > capacity:
                        repaired.append(current)
                        current = [c]
                        current_load = dc
                    else:
                        current.append(c)
                        current_load += dc
                if current:
                    repaired.append(current)

    final_routes = repaired

    # Any still-missing customers get singleton routes
    assigned2 = {}
    for r in final_routes:
        for c in r:
            assigned2[c] = True
    for c in customer_ids:
        if c not in assigned2:
            final_routes.append([c])

    return final_routes
